using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using Racer;using Object=UnityEngine.Object;
public static class CheckMountainCutRecovery {public static string Main(){var race=Object.FindAnyObjectByType<RaceDirector>();var r=race.vehicle.GetComponent<VehicleRespawn>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(VehicleRespawn).GetMethod("MeasureClearance",flags).Invoke(r,null);var supported=typeof(VehicleRespawn).GetMethod("Supported",flags);var clear=typeof(VehicleRespawn).GetMethod("Clear",flags);var branch=race.Branches.Single(b=>b.title=="Summit Traverse");var points=new List<(string,Vector3,Vector3)>();foreach(float s in new[]{870f,895f,910f,925f,937f}){var p=race.road.At(s,out var f);points.Add(("main "+s,p,f));}foreach(float s in new[]{60f,140f,220f,330f}){var p=branch.At(s,out var f);points.Add(("upper "+s,p,f));}var lines=new List<string>();foreach(var p in points){object[] args={p.Item2,Vector3.ProjectOnPlane(p.Item3,Vector3.up).normalized,Vector3.zero,Quaternion.identity};bool floor=(bool)supported.Invoke(r,args);bool open=floor&&(bool)clear.Invoke(r,new[]{args[2],args[3]});lines.Add($"{p.Item1}: supported={floor}, full rider/body clearance={open}");}File.WriteAllLines("Docs/MountainCut/recovery-checks.txt",lines);return string.Join("\n",lines);}}
